import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** Primary key: UUIDv7 generated by PostgreSQL 18 (`uuidv7()`), concept chapter 3. */
export const id = () => uuid("id").primaryKey().default(sql`uuidv7()`);

/** Timestamps are always stored in UTC (`timestamptz`). */
export const tz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

export const createdAt = () => tz("created_at").notNull().defaultNow();
export const updatedAt = () =>
  tz("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
export const deletedAt = () => tz("deleted_at");

export const timestamps = () => ({
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});
